/// What a surface tells its client.
///
/// SEPARATE EVENTS AND NOT ONE "SOMETHING CHANGED". A client that has to re-read everything to find
/// out what happened re-reads everything sixty times a second.
#[derive(Clone, Debug, PartialEq)]
pub enum SurfaceEvent {
	/// The atomic snapshot. The client rebuilds and acknowledges by serial.
	Configure(SurfaceConfiguration),
	/// WHAT A CLIENT WAITS ON INSTEAD OF BLOCKING INSIDE `acquire-next`, which is what keeps one
	/// dispatch loop alive.
	ImageAvailable,
	/// A present's fate, reported PER PRESENT rather than inferred from the next acquire.
	PresentComplete(PresentComplete),
	/// A REQUEST AND NOT A TEARDOWN: the application decides, which is what makes an unsaved-changes
	/// prompt possible.
	CloseRequested,
	/// A background client stops drawing rather than discovering it by a refusal.
	VisibilityChanged(bool),
	/// Focus belongs to the surface, so the event does too.
	FocusChanged(bool),
}

impl SurfaceEvent {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<SurfaceEvent> {
		let mut r = Reader::new(bytes);
		let value = SurfaceEvent::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<SurfaceEvent> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = SurfaceEvent::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		match self {
			SurfaceEvent::Configure(v8) => {
				w.u8(0)?;
				v8.write(w)?;
			}
			SurfaceEvent::ImageAvailable => {
				w.u8(1)?;
			}
			SurfaceEvent::PresentComplete(v9) => {
				w.u8(2)?;
				v9.write(w)?;
			}
			SurfaceEvent::CloseRequested => {
				w.u8(3)?;
			}
			SurfaceEvent::VisibilityChanged(v10) => {
				w.u8(4)?;
				w.boolean(*v10)?;
			}
			SurfaceEvent::FocusChanged(v11) => {
				w.u8(5)?;
				w.boolean(*v11)?;
			}
		}
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<SurfaceEvent> {
		match r.u8()? {
			0 => Some(SurfaceEvent::Configure(SurfaceConfiguration::read(r)?)),
			1 => Some(SurfaceEvent::ImageAvailable),
			2 => Some(SurfaceEvent::PresentComplete(PresentComplete::read(r)?)),
			3 => Some(SurfaceEvent::CloseRequested),
			4 => Some(SurfaceEvent::VisibilityChanged(r.boolean()?)),
			5 => Some(SurfaceEvent::FocusChanged(r.boolean()?)),
			_ => None,
		}
	}
}

/// What `acquire-next` answers.
///
/// IT DOES NOT BLOCK, and that is a property of the service rather than a preference: handlers are
/// synchronous and one dispatch loop serves the backend, the admin channel and every client.
/// Blocking inside an acquire handler stops the only loop that could deliver the release that would
/// unblock it, so a conforming implementation would deadlock under ordinary queue pressure.
