/// The images of a surface's present queue, as the client sees them.
///
/// THE COUNT IS NEGOTIATED AND IS NOT IN THE INTERFACE. The service advertises a minimum and a
/// maximum, the client asks, and the service answers with what it gave - so a number nobody agreed
/// to cannot be written into the ABI.
#[derive(Clone, Debug, PartialEq)]
pub struct PresentQueue {
	/// How many images the queue has, and therefore how many the client must SUPPLY. They are
	/// provided ONE AT A TIME by `provide-image`, because a message carrying a LIST of capabilities
	/// has a count no schema can bound - and a decode that stopped part way could not hand back the
	/// handles it had already taken.
	pub images: u32,
	pub pitch: u32,
	pub generation: u64,
	/// The client's end of PRODUCER_READY, carrying SEND alone.
	pub producer: u64,
	/// The client's end of PRESENT_DONE, carrying RECEIVE and WAIT.
	pub done: u64,
}

impl PresentQueue {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<PresentQueue> {
		let mut r = Reader::new(bytes);
		let value = PresentQueue::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<PresentQueue> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = PresentQueue::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.u32(self.images)?;
		w.u32(self.pitch)?;
		w.u64(self.generation)?;
		w.set_handle(self.producer)?;
		w.u32(0)?;
		w.set_handle(self.done)?;
		w.u32(0)?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<PresentQueue> {
		let images = r.u32()?;
		let pitch = r.u32()?;
		let generation = r.u64()?;
		let producer = {
			let _ = r.u32()?;
			r.take_handle()?
		};
		let done = {
			let _ = r.u32()?;
			r.take_handle()?
		};
		Some(PresentQueue { images, pitch, generation, producer, done })
	}
}

